\documentclass{article}
\usepackage{amsmath}
\usepackage{pgfplots}
\usepackage{tikz}
\usepackage{tikz-3dplot}
\usetikzlibrary{arrows}
\usetikzlibrary{positioning}
\usetikzlibrary{intersections}
\usepgfplotslibrary{fillbetween}
\usepackage{tkz-euclide}
\usepackage{ifthen}
\usetkzobj{all}

\newcommand{\myCylinder}[6]{
\tdplotsetmaincoords{#2}{0}
	\begin{scope}[tdplot_main_coords, scale=#6]
    \coordinate (O) at (0,0,#3);
    \coordinate (O2) at (0,0,0);
    \coordinate (B) at (#1,0,0);
    \coordinate (E) at (#1,0,#3);
    \coordinate (A) at (-#1,0,0);
    \coordinate (F) at (-#1,0,#3);


    \begin{scope}[canvas is xy plane at z=0]
            \draw[color=#4!20,fill=#4!20,fill opacity=#5,opacity=#5] (O2) circle (#1);

            % '%' for no lid, no '%' for lid
            \draw[color=#4!20,fill=#4!10,fill opacity=#5,opacity=#5] (O) circle (#1);

            \draw[very thick, #4,dashed] (B) arc (0:180:#1);
            \draw[very thick, #4,left color=#4!40, right color=#4!70, middle color=#4!30,fill opacity=#5] (B) arc  (0:-180:#1)-- (F) arc  (-180:0:#1) --cycle;

            \draw[very thick, #4] (F) arc (180:0:#1);


	\end{scope}

    %\draw(E) -- (B) (A)--(F);
    \tkzLabelSegment[right](E,B){ {$h$}}
    \tkzLabelSegment[above](E,O){ {$r$}}
    %\tkzLabelSegment[right](E,B){ {$h\,\textrm{cm}$}}
    %\tkzLabelSegment[above](E,O){ {$r\,\textrm{cm}$}}
    \tkzDrawPoint[color=#4, fill=#4](O)
    \tkzDrawSegment[very thick, #4](E,O)

	\end{scope}
}

\begin{document}
\pagestyle{empty}

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\tdplotsetmaincoords{70}{0}
\begin{tikzpicture}[ scale=1.0, rounded corners=0.1mm, rotate=0]%tdplot_main_coords

\myCylinder{2.5}{60}{5}{orangepeel}{0.6}{0.5};

% #1: radius
% #2: depth
% #3: height
% #4: color
% #5: fill opacity
% #6: scale

\end{tikzpicture}

\end{document}

